def policy(observed, context):
    calls = len(observed) - 1
    limit = max(1, int(4 * (1 - .75 * context['rho']) + .9999))
    if calls >= limit or max(n['score'] for n in observed) >= 1:
        return []
    if calls == 0:
        return ['root']
    parents = {n['parent'] for n in observed}
    leaves = [n for n in observed if n['id'] != 'root' and n['id'] not in parents]
    leaves.sort(key=lambda n: (-n['score'], n['id']))
    return [leaves[0]['id']]

def policy(observed, context):
    candidates = [n for n in observed if n['id'] != 'root']
    if not candidates:
        return ['root']
    best = max(n['score'] for n in candidates)
    required = 1 - .1 * context['rho']
    if best >= required or context['remaining_calls'] <= 0:
        return []
    parents = {n['parent'] for n in observed}
    leaves = [n for n in candidates if n['id'] not in parents]
    return [max(leaves, key=lambda n: n['score'])['id']]

def policy(observed, context):
    nodes = [n for n in observed if n['id'] != 'root']
    if not nodes:
        return ['root']
    if max(n['score'] for n in nodes) >= 1:
        return []
    ceiling = max(1, int(4 * (1 - .75 * context['rho']) + .9999))
    if len(nodes) >= ceiling:
        return []
    by_id = {n['id']: n for n in observed}
    parents = {n['parent'] for n in observed}
    leaves = [n for n in nodes if n['id'] not in parents]
    successful = [n for n in leaves if n['score'] > 0]
    if not successful:
        failed = leaves[-1]
        if failed.get('observation', {}).get('error_type') in ['SyntaxError', 'ValueError']:
            return [failed['id']]
        return ['root']
    def priority(node):
        gain = node['score'] - by_id[node['parent']]['score']
        return node['score'] + (1 - context['rho']) * max(0, gain)
    return [max(successful, key=priority)['id']]

