def exact_pack(weights, capacity):
    count = len(weights)
    if count == 0:
        return []
    states = 1 << count
    best = [(count + 1, capacity + 1)] * states
    choices = [None] * states
    best[0] = (1, 0)
    for mask in range(1, states):
        for index in range(count):
            bit = 1 << index
            if mask & bit:
                previous = mask ^ bit
                bins, load = best[previous]
                new_bin = load + weights[index] > capacity
                candidate = (bins + 1, weights[index]) if new_bin else (bins, load + weights[index])
                if candidate < best[mask]:
                    best[mask] = candidate
                    choices[mask] = (index, new_bin)
    actions = []
    mask = states - 1
    while mask:
        index, new_bin = choices[mask]
        actions.append((index, new_bin))
        mask ^= 1 << index
    bins = [[]]
    for index, new_bin in reversed(actions):
        if new_bin and bins[-1]:
            bins.append([])
        bins[-1].append(index)
    return bins
def greedy_pack(weights, capacity):
    bins = []
    loads = []
    order = sorted(range(len(weights)), key=lambda i: -weights[i])
    for index in order:
        placed = False
        for position in range(len(bins)):
            if loads[position] + weights[index] <= capacity:
                bins[position].append(index)
                loads[position] += weights[index]
                placed = True
                break
        if not placed:
            bins.append([index])
            loads.append(weights[index])
    return bins
def pack(weights, capacity):
    greedy = greedy_pack(weights, capacity)
    lower = (sum(weights) + capacity - 1) // capacity
    if len(greedy) == lower:
        return greedy
    return exact_pack(weights, capacity)

def policy(observed, context):
    nodes = [n for n in observed if n['id'] != 'root']
    if not nodes:
        return ['root']
    best = max(n['score'] for n in nodes)
    if best >= 1:
        return []
    budget = max(1, math.ceil(4 * (1 - .75 * context['rho'])))
    if len(nodes) >= budget:
        return []
    parents = {n['parent'] for n in observed}
    leaves = [n for n in nodes if n['id'] not in parents and n['id'] in context['legal_parents']]
    if not leaves:
        return ['root']
    scores = {n['id']: n['score'] for n in observed}
    def priority(node):
        gain = max(0, node['score'] - scores.get(node['parent'], 0))
        return node['score'] + (1 - context['rho']) * gain
    return [max(leaves, key=priority)['id']]

